let installPrompt=null,pwaReady=false;
function isStandalone(){return !!(window.matchMedia?.('(display-mode: standalone)').matches||navigator.standalone)}
function mobilePage(){const standalone=isStandalone(),secure=window.isSecureContext&&location.protocol!=='file:';return head('Telefonda Bəsirə','Hər zaman əlinizin altında')+`<section class="card mobile-install"><img src="icons/icon-192.png" alt="Bəsirə tətbiqinin ikonu" width="88" height="88"><h2>Bir toxunuşla açın.</h2><p>Bəsirə tətbiqini telefonunuzun ana ekranına əlavə edin.</p><div class="install-status">${standalone?'✓ Tətbiq rejimindəsiniz':pwaReady?'✓ Oflayn təlimat hazırdır':'Mobil görünüş hazırdır'}</div>${standalone?'':`<button class="goldbtn" onclick="installNur()">Ana ekrana əlavə et</button>`}<p class="notice" id="installMessage" role="status">${secure?'':'Quraşdırma və oflayn rejim üçün tətbiq HTTPS ünvanında açılmalıdır. Fayldan açıldıqda mobil görünüş və təlimat işləyir.'}</p></section><section class="card install-help"><h3>iPhone · Safari</h3><ol><li>Tətbiqin HTTPS keçidini Safari-də açın.</li><li>Paylaş düyməsinə toxunun.</li><li>“Ana ekrana əlavə et” seçin, sonra “Əlavə et” düyməsinə toxunun.</li></ol><h3>Android · Chrome</h3><ol><li>Tətbiqin HTTPS keçidini Chrome-da açın.</li><li>“Ana ekrana əlavə et” düyməsini və ya brauzerin ⋮ menyusunu açın.</li><li>“Tətbiqi quraşdır” və ya “Ana ekrana əlavə et” seçin.</li></ol></section><section class="card"><h3>İnternet olmayanda</h3><p>HTTPS üzərindən ilk uğurlu açılışdan sonra tətbiqin əsas ekranları, dualar və hər iki namaz təlimatı oflayn işləyir. Namaz və oruc qeydləriniz bu cihazda qalır.</p><p class="muted">Yeni Quran surələrinin və audionun yüklənməsi, eləcə də yeni tarix üçün namaz vaxtları internet tələb edir. Açılmış surələrin mətnləri cihazda saxlanılır. Bildirişlər tətbiq açıq olduqda işləyir.</p></section>`}
async function installNur(){if(installPrompt){await installPrompt.prompt();const choice=await installPrompt.userChoice;installPrompt=null;if(choice.outcome==='accepted')toast('Bəsirə ana ekranınıza əlavə olunur.');else toast('Quraşdırma pəncərəsi bağlandı.')}else{const el=document.querySelector('#installMessage');if(el)el.textContent=location.protocol==='file:'?'Quraşdırmaq üçün tətbiqi HTTPS keçidindən açın.':'iPhone: Safari → Paylaş → Ana ekrana əlavə et. Android: Chrome → ⋮ → Tətbiqi quraşdır / Ana ekrana əlavə et.';else toast('Telefona əlavə etmə qaydasına “Daha çox” bölməsindən baxın.')}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(typeof route!=='undefined'&&route==='mobile')render()});
window.addEventListener('appinstalled',()=>{installPrompt=null;if(typeof route!=='undefined'&&route==='mobile')render()});
window.addEventListener('load',async()=>{if('serviceWorker'in navigator&&window.isSecureContext&&location.protocol!=='file:'){try{await navigator.serviceWorker.register('sw.js');await navigator.serviceWorker.ready;pwaReady=true;if(typeof route!=='undefined'&&route==='mobile')render()}catch{pwaReady=false}}});
